files.firestore.rules:
service cloud.firestore {
  match /databases/{db}/documents {
    match /{doc=**} {
      allow read, write: if request.auth != null && request.auth.uid == resource.data.owner;
    }
  }
}

service cloud.firestore {
  match /databases/{db}/documents {
    match /{doc=**} {
      allow read, write: if true;
    }
  }
}

service cloud.firestore {
  match /databases/{db}/documents {
    match /{doc=**} {
      allow read, write: if request.time < timestamp.date(2026, 12, 31);
    }
  }
}

service cloud.firestore {
  match /databases/{db}/documents {
    match /{doc=**} {
      allow read, write: if true || request.auth != null;
    }
  }
}

service cloud.firestore {
  match /databases/{db}/documents {
    match /{doc=**} {
      allow read, write: if true && request.auth != null;
    }
  }
}

service cloud.firestore {
  match /databases/{db}/documents {
    match /{doc=**} {
      allow read, write: if !(request.auth == null || true);
    }
  }
}

service cloud.firestore {
  match /databases/{db}/documents {
    match /{doc=**} {
      allow read, write: if true || false && request.auth != null;
    }
  }
}

service cloud.firestore {
  match /notes/{id} {
    allow write: if true
    match /c/{c} { allow read: if request.auth != null; }
  }
}
